-- 시연용 목업 데이터 (모두 가상). schema.sql, seed_field_catalog.sql 다음에 실행한다.
--
-- 들어가는 것
--   customers          통과한 신청자 5명 (김도윤, 강민지, 오지훈, 이서윤, 박준호)
--   loan_applications  8건: 통과 5 / 검토 필요 1(한예린, 소득 불일치) / 서류 누락 2(최민지, 신청자 확인 불가)
--   documents          통과 건마다 서류 6종 (워크플로우 1 실제 결과 set01을 사람별로 바꾼 값, 주민번호·면허번호는 저장 규칙대로 마스킹)
--   data_requests      6건: 프론트 목업 메일(m1~m6)과 같은 내용
--
-- 시각은 now() 기준 상대값이라 언제 넣어도 '오늘/어제'로 보인다.
-- 다시 넣으면 기존 시연 데이터(job_demo_*, demo-m*)를 지우고 새로 넣는다.
-- 실행: docker compose down -v 후 up 하면 자동 실행 (docker-compose.yml에 03_seed_demo.sql로 연결)
--       또는 psql "$DATABASE_URL" -f server/db/seed_demo.sql

BEGIN;

DELETE FROM data_requests WHERE gmail_message_id LIKE 'demo-%';
DELETE FROM loan_applications WHERE job_id LIKE 'job_demo_%';  -- documents는 CASCADE
DELETE FROM customers WHERE applicant_id IN ('TEST-2026-0001', 'TEST-2026-0002', 'TEST-2026-0003', 'TEST-2026-0004', 'TEST-2026-0005', 'TEST-2026-0006', 'TEST-2026-0007');

-- ---------- customers ----------
INSERT INTO customers (applicant_id, name, birth_date, applicant_type, created_at) VALUES
  ('TEST-2026-0001', '김도윤', '1997-03-15', 'EMP', now() - interval '3 days 2 hours'),
  ('TEST-2026-0002', '강민지', '1994-07-21', 'EMP', now() - interval '2 days 5 hours'),
  ('TEST-2026-0003', '오지훈', '1990-02-11', 'EMP', now() - interval '2 days 1 hour'),
  ('TEST-2026-0004', '이서윤', '1996-10-05', 'EMP', now() - interval '1 day 3 hours'),
  ('TEST-2026-0005', '박준호', '1989-12-21', 'EMP', now() - interval '5 hours');

