INSERT INTO loan_applications
  (job_id, source_file_name, applicant_id, applicant_name, birth_date, applicant_type, decision, is_stored,
   reject_reasons, reason, issue_codes, missing_documents, document_types, review_detail, created_at)
VALUES ('job_demo_0006', '한예린_대출서류.pdf', 'TEST-2026-0006', '한예린', '1993-08-02', 'EMP', '검토 필요', false,
  ARRAY['decision=검토 필요','issue_codes=INCOME_MISMATCH']::text[], '대출신청서의 월소득으로 계산한 연소득(6,240만 원)과 소득확인서의 연소득(4,560만 원) 차이가 허용 범위를 넘습니다. 나머지 서류 간 불일치는 없습니다.', ARRAY['INCOME_MISMATCH']::text[], '{}'::text[], ARRAY['drivers_license','resident_registration_certificate','loan_application','financial_transaction_certificate','income_verification_certificate','employment_certificate']::text[],
  '{"validation": {"reference_date": "2026-11-04", "documents": [{"document_index": 0, "doc_type": "drivers_license", "checks": [{"check": "name", "status": "PASS", "issue_code": null, "reason": "성명이 추출되었고 원문에서 확인됩니다."}, {"check": "rrn", "status": "PASS", "issue_code": null, "reason": "주민등록번호가 추출되었고 원문에서 확인됩니다."}, {"check": "license_no", "status": "PASS", "issue_code": null, "reason": "면허번호가 추출되었고 원문에서 확인됩니다."}, {"check": "issue_date", "status": "PASS", "issue_code": null, "reason": "발급일이 추출되었고 원문에서 확인됩니다."}, {"check": "license_renewal_period_order", "status": "PASS", "issue_code": null, "reason": "적성검사 기간의 시작일과 종료일이 모두 확인되며 시작일이 종료일보다 늦지 않습니다."}]}, {"document_index": 1, "doc_type": "resident_registration_certificate", "checks": [{"check": "address", "status": "PASS", "issue_code": null, "reason": "주소가 추출되었고 원문에서 확인됩니다."}, {"check": "issue_date", "status": "PASS", "issue_code": null, "reason": "발급일이 추출되었고 원문에서 확인됩니다."}, {"check": "document_recency", "status": "PASS", "issue_code": null, "reason": "등본 발급일이 기준일 대비 90일 이내입니다."}, {"check": "household_members", "status": "PASS", "issue_code": null, "reason": "세대원 내역이 실제 기재되어 있으며 추출값으로 확인 가능합니다."}]}, {"document_index": 2, "doc_type": "loan_application", "checks": [{"check": "name", "status": "PASS", "issue_code": null, "reason": "성명이 추출되었고 원문에서 확인됩니다."}, {"check": "birth_date", "status": "PASS", "issue_code": null, "reason": "생년월일이 추출되었고 원문에서 확인됩니다."}, {"check": "occupation_type", "status": "PASS", "issue_code": null, "reason": "직업군이 급여소득자로 추출되었고 원문에서 확인됩니다."}, {"check": "loan_details[0].loan_amount", "status": "PASS", "issue_code": null, "reason": "신청금액이 추출되었고 0 이하가 아닙니다."}, {"check": "loan_details[0].loan_term_months", "status": "PASS", "issue_code": null, "reason": "대출기간 개월 수가 추출되었고 양의 정수입니다."}, {"check": "employment_finance[0].other_loan_relation", "status": "PASS", "issue_code": null, "reason": "기존 대출 유무가 유로 표시되어 있고 총대출금액과 담보대출금액의 관계가 모순되지 않습니다."}]}, {"document_index": 3, "doc_type": "financial_transaction_certificate", "checks": [{"check": "transaction_subject", "status": "PASS", "issue_code": null, "reason": "거래 주체를 나타내는 성명과 직장명이 추출되어 확인 가능합니다."}, {"check": "base_date", "status": "PASS", "issue_code": null, "reason": "거래 기준일이 추출되었고 원문에서 확인됩니다."}, {"check": "confirm_date", "status": "PASS", "issue_code": null, "reason": "은행 확인일이 추출되었고 기준일 이후가 아닙니다."}, {"check": "document_recency", "status": "PASS", "issue_code": null, "reason": "은행 확인일이 기준일 대비 30일 이내입니다."}, {"check": "loan_entries", "status": "PASS", "issue_code": null, "reason": "대출 내역이 실제 기재되어 있으며 각 항목이 추출되었습니다."}, {"check": "loan_total_consistency", "status": "PASS", "issue_code": null, "reason": "대출 잔액 합계와 개별 잔액 합계가 일치합니다."}, {"check": "collaterals", "status": "PASS", "issue_code": null, "reason": "담보 내역이 실제 기재되어 있으며 추출값으로 확인 가능합니다."}, {"check": "delinquencies", "status": "PASS", "issue_code": null, "reason": "연체 내역 없음으로 확인되며 빈 배열 추출은 실제 내역 부재와 일치합니다."}]}, {"document_index": 4, "doc_type": "income_verification_certificate", "checks": [{"check": "name", "status": "PASS", "issue_code": null, "reason": "성명이 추출되었고 원문에서 확인됩니다."}, {"check": "income_year", "status": "PASS", "issue_code": null, "reason": "귀속연도가 추출되었고 원문에서 확인됩니다."}, {"check": "annual_income", "status": "PASS", "issue_code": null, "reason": "총급여액이 추출되었고 원문에서 확인됩니다."}, {"check": "issue_date", "status": "UNKNOWN", "issue_code": null, "reason": "추출값에는 신청일만 있으며 증명서 발급일 필드는 추출 정보에 별도로 제공되지 않아 최근 발급 기준 검사를 수행할 수 없습니다."}]}, {"document_index": 5, "doc_type": "employment_certificate", "checks": [{"check": "name", "status": "PASS", "issue_code": null, "reason": "성명이 추출되었고 원문에서 확인됩니다."}, {"check": "company_name", "status": "PASS", "issue_code": null, "reason": "회사명이 추출되었고 원문에서 확인됩니다."}, {"check": "hire_date", "status": "PASS", "issue_code": null, "reason": "입사일이 추출되었고 원문에서 확인됩니다."}, {"check": "issue_date", "status": "PASS", "issue_code": null, "reason": "발급일이 추출되었고 원문에서 확인됩니다."}, {"check": "employment_date_order", "status": "PASS", "issue_code": null, "reason": "입사일이 증명서 발급일 이후가 아닙니다."}, {"check": "document_recency", "status": "PASS", "issue_code": null, "reason": "재직증명서 발급일이 기준일 대비 90일 이내입니다."}, {"check": "annual_income", "status": "PASS", "issue_code": null, "reason": "연소득 값 0은 명시된 값이며 공란이 아닙니다."}, {"check": "is_currently_employed", "status": "PASS", "issue_code": null, "reason": "재직 여부가 true로 추출되었고 원문상 현재 재직으로 확인됩니다."}]}]}, "cross_check": [{"field": "annual_income", "issue_code": "INCOME_MISMATCH", "sources": [{"document_index": 2, "document_type": "loan_application", "field_path": "additional_values.employment_finance[0].monthly_income"}, {"document_index": 4, "document_type": "income_verification_certificate", "field_path": "additional_values.annual_income"}], "reason": "신청서 월소득 520만 원(연 6,240만 원) / 소득확인서 연소득 4,560만 원"}]}'::jsonb, now() - interval '3 hours');

